"""Shared release history for the full page and personal missed updates."""
RELEASES = [
    ("5.1.0", "Regalansichten, animierte Helfer und Pokémon-Zuordnung", "Kacheln, Holzregal und Schwarzglas unter Konto auswählen. Animierte Regalhelfer, Medienlinks und Größensortierung. Games-Zugang im Medienassistenten, MusicBrainz-Musikbestimmung und verbesserte Pokémon-Editionstitel."),
    ("5.1.0-rc.22", "Prüfentwurf: Medien stehen auf dem Regalbrett", "Regalbretter liegen direkt unter den Medien statt an einer festen Höhe über dem Kachelende. Hüllenunterkanten und Perspektive erhalten eine gemeinsame Auflage. Helfer nutzen die tatsächliche Brettposition. Enthält alle vorherigen Korrekturen."),
    ("5.1.0-rc.21", "Prüfentwurf: Sammelkarten-Fach als Eingang", "Die echte Beschriftungsfläche des Sammelkarten-Fachs schwenkt als Tür auf. Laufposen folgen der Laufrichtung; herausgezogene Hüllen liegen vor der Regalkante. Helfer und Wächterin nutzen diesen Eingang; nach Ende der Szene schließt sich die Kachel wieder. Musik bestimmen mit sichtbarer MusicBrainz-Suche und getrennten Interpret-/Album-Feldern. Enthält Detektive, Rapper und den Piratenhut-Fix."),
    ("5.1.0-rc.20", "Prüfentwurf: versteckte Tür, Detektive & Rapper", "Ein angehobenes Regalbrett gibt die Tür frei. Figuren laufen davor, ohne Namensschilder. Der Piratenhut bleibt beim Klettern erhalten. Sechs Detektive und fünf Rapper ergänzen die Helfer."),
    ("5.1.0-rc.19", "Prüfentwurf: Piratencrew", "Sechs Piraten mit Lauf-, Kletter- und Aktionsposen ergänzen die Regalhelfer. Sie räumen mit einem kurzen Enthüllungseffekt ein. Enthält den Türsteher-Aufbau und alle bisherigen Korrekturen."),
    ("5.1.0-rc.18", "Prüfentwurf: Türsteher bauen die Leitern", "Sportlerposen direkt eingebunden. Vier verschiedene Türsteher bauen Leitern auf und ziehen sich zurück; eine Wächterin bleibt an der Tür. Nach Rückkehr aller Helfer holt das Team die Leitern wieder herein."),
    ("5.1.0-rc.17", "Prüfentwurf: saubere Sprite-Ausschnitte & Schuss", "Einzelne Sprite-Konturen statt fester Rasterausschnitte, Füße auf gemeinsamer Grundlinie. Ausholen, Kontakt und Nachschwingen vor dem Ballflug. Jeder Charakter erscheint pro Szene höchstens einmal."),
    ("5.1.0-rc.16", "Prüfentwurf: Sportler & Ball-Verwandlung", "Fünf Sportler mit Pixel-Laufposen. Fußball und Tennisball fliegen ins Fach und verwandeln sich dort in das einzuräumende Medium. Enthält alle bisherigen Prüfstände."),
    ("5.1.0-rc.15", "Prüfentwurf: bewegliche Gelenke & Türsteher-Rückweg", "Deutlichere Bewegungen mit Schultern, Ellenbogen, Oberschenkeln und Knien. Nach seiner Geste geht auch der Türsteher hinein. Erst danach schließt und verschwindet die Tür im unteren Regalbereich; der zusätzliche Sockel ist entfernt."),
    ("5.1.0-rc.14", "Prüfentwurf: ruhigere Helferbewegungen", "Ernster Türwächter, nur während des Easter Eggs sichtbare Tür, weichere Lauf- und Kletterwege, gegenläufige Schritte und natürliche Armbewegungen. Auf dem Hin- und Rückweg tragen die Helfer noch keine Medien."),
    ("5.1.0-rc.13", "Prüfentwurf: Helfertür, Leitern & Kontoansicht", "Größere, beschriftete Helfer kommen aus einer Tür, klettern zu ihren Fächern, räumen langsam ein und steigen wieder hinunter. Der Türwächter reagiert erst nach ihrer Rückkehr. Dashboardansicht wird jetzt in den Kontoeinstellungen gespeichert."),
    ("5.1.0-rc.12", "Prüfentwurf: persönliche Dashboardansicht & sortiertes Regal", "Persönliche Wahl zwischen ursprünglichen Kacheln, Holzregal und Schwarzglas. Medien bleiben nach Größe sortiert, auch beim Titelwechsel. Mario, Luigi, Hitman, Walter White, Conan, Ash und Kool Savas als stilisierte Helfer mit eigenen Aktionen räumen das Regal langsamer wieder ein."),
    ("5.1.0-rc.11", "Prüfentwurf: Regalschrauben & kleine Helfer", "Drei funktionslose Zierschrauben ergänzen die versteckte Rüttelschraube. Nach dem Herausfallen räumen kleine Gaming- und Filmfiguren das Regal wieder ein. Mario-, Zelda- und FIFA-Themen richten sich nach vorhandenen Titeln. Reduzierte Bewegung wird berücksichtigt."),
    ("5.1.0-rc.10", "Prüfentwurf: verstecktes Regal-Easter-Egg", "Der Rüttelknopf ist als kleine Schraube im unteren Holzrahmen versteckt. Tastaturbedienung, automatische Wiederherstellung und reduzierte Bewegung bleiben erhalten. Enthält alle vorherigen 5.1.0-Prüfstände."),
    ("5.1.0-rc.9", "Prüfentwurf: vollständige Medienhüllen & Direktlinks", "Realistischere Hüllen mit Tiefe, Oberkante, Coverseite und Formatbändern. Beschriftete Rücken öffnen den jeweiligen Eintrag. Der letzte unbeschriftete Rücken und das Schild führen zur Kategorie. Automatischer Wechsel aktualisiert Titel und Ziel gemeinsam; der Kategorienrücken bleibt frei. Holzregal, zwei Fächer pro Reihe auf Handy/Tablet und Rüttel-Easter-Egg."),
    ("5.1.0-rc.8", "Prüfentwurf: gefülltes Medienregal", "Schmale Rücken mit zufällig ausgewählten Sammlungstiteln und passenden Farben und Größen für DVD, Blu-ray und Spieleplattformen. Einzelne Hüllen bewegen sich räumlich nach vorne. Kategoriennamen stehen unter dem Fach; leere Weitere Sammlungen werden ausgeblendet. Automatischer Titelwechsel mit Pausenschalter. Kompakte mobile Navigation mit Menükacheln untereinander."),
    ("5.1.0-rc.7", "Prüfentwurf: interaktives Sammlungsregal", "Dashboard-Kategorien als farbige Buchrücken, Medienhüllen und Alben im Regal. Beschriftete Rücken öffnen die Kategorie; ein freies Fach führt zur neuen Kategorie. Bestand, Wert, Tastaturbedienung und Leserechte bleiben erhalten. Enthält die Stabilitätsfixes aus rc.6."),
    ("5.1.0-rc.6", "Prüfentwurf: Preisqualität, Speicherprüfung & Update-Backups", "Warnungen für alte oder unsichere Preise und eBay-Angebotsreferenzen; erkennbare Regions-/Editionskonflikte ausgeschlossen. Ungültige Geldbeträge und Kaufdaten werden vor Änderungen abgefangen. Defekte Bilder erhalten einen Platzhalter. Update sichert Datenbank und Uploads mit isolierter Wiederherstellungsprobe."),
    ("5.1.0-rc.5", "Prüfentwurf: persönliche Besitzer statt allgemeiner Admin-Konten", "Die allgemeinen Konten admin und test-admin erscheinen nicht als Besitzer in der globalen Top 10. Persönliche Administratoren bleiben sichtbar. Cover, einzelne Exemplare und Preisgleichstände bleiben unverändert."),
    ("5.1.0-rc.4", "Prüfentwurf: Top-10-Cover & Besitzer", "Globale Top 10 mit Cover und Besitzer-Benutzernamen. Gemeinsam verwaltete Sammlungen zeigen ihre zugeordneten Administratoren, keine technischen Konten. Gleiche Produkte bleiben je Exemplar separat sichtbar; Preisgleichstand am zehnten Platz schließt alle gleichwertigen Exemplare ein."),
    ("5.1.0-rc.3", "Prüfentwurf: Top-10-Standardfreigabe & OVP-Feld", "Globale Top 10 und Teilnahme sind ab zwei Sammlungsdatenbanken standardmäßig aktiv, mit neutralen Anzeigenamen und jederzeitiger Abmeldung. Gespeicherte Abmeldungen bleiben bestehen. Tutorial-Einstellungen erhalten eine hervorgehobene Speicheraktion. OVP-Zustand ist ohne vorhandene OVP gesperrt und wird beim Speichern ignoriert."),
    ("5.1.0-rc.2", "Prüfentwurf: Meldungsabschluss, Tutorial-Schalter & verpasste Updates", "Nutzer schließen Meldungen für sich ab, ohne Admin-Aufgaben zu erledigen. Eigene offene Meldungen und Admin-Aufgaben sind getrennt. Tutorials lassen sich dauerhaft ausschalten. Alle dokumentierten Update-Einträge seit dem vorherigen Login erscheinen chronologisch, einschließlich übersprungener Versionen."),
    ("5.1.0-rc.1", "Prüfentwurf: Meldungseinstufung, Nachrichten & TU-Freigabe", "Lokale Kategorie-/Dringlichkeitsvorschläge, offene Admin-Meldungen, persönliche Antworten und Statusnachrichten, dokumentierte Testfreigabe und bewusster Produktionsbefehl. Einheitliche RC-/Release-Nummern."),
    ("5.0.4", "Freigegebener Release: Dashboard-Tour & Testzugang", "Farbiges Bücherregal, geführte Einführung direkt im Dashboard, Testbanner, passwortloser Test-admin und Desktop-Bash-Starter; enthält die vorherigen 5.0-Prüfentwürfe."),
    ("5.0.3", "Prüfentwurf: zuverlässiger Docker-Start", "Einmalige Datenbankinitialisierung vor Web-Workern und Scheduler; sichtbare Healthcheck-Wartephase und frühzeitige Fehlerausgabe."),
    ("5.0.2", "Prüfentwurf: Einführung & Testmigration", "Robustere Release-Bestätigung, überspringbares Einführungstutorial und Kopieren von Produktionsdaten in die isolierte Docker-Testumgebung."),
    ("5.0.1", "Zweiter Prüfentwurf: globale Top 10 & Release-Hinweise", "Menübuttons, freiwillige globale Ranglisten mit persönlichem Schalter ab zwei Sammlungen, einmaliger Hinweis pro Nutzer/Version und separate Docker-Testumgebung."),
    ("5.0.0", "Prüfentwurf: verständliche Navigation & privates Feedback", "Menüs erklären Funktionen und bieten eine Suche. Nutzer können Meldungen mit Bildern senden; Systemadministratoren verwalten Status, Zielversion, Antworten und interne Notizen."),
    ("4.7.1", "Symbolauswahl & flexibler Installer", "Eigene Kategorien erhalten Standardicons oder ein eigenes Emoji. Die Löschbestätigung ist kompakter, das Startskript findet Pakete lokal und auf GitHub."),
    ("4.7.0", "Eigene Sammlungskategorien verwalten", "Eigene Dashboard-Bereiche bearbeiten oder entfernen und mehrere Objekte gemeinsam verschieben. Beim Entfernen einer Kategorie bleiben alle Objekte erhalten."),
    ("4.6.5", "Private Rechteverwaltung & sauberer Release-Workflow", "Sammlungsverwalter sehen nur Mitglieder und konkrete Zugriffsanfragen ihrer Sammlung. Eigene Kategorien führen direkt zum ersten Objekt und leere Sammlungen zeigen keine fremden Spielreihen mehr."),
    ("4.6.4", "Getrennte Spielreihen & eigene Dashboard-Bereiche", "Spielreihen erscheinen nur für die aktive Sammlung; zusätzlich lassen sich beliebig viele eigene Sammlungskategorien mit Name und Symbol direkt zum Start- und Bewertungsdashboard hinzufügen."),
    ("4.6.3", "Weitere Exemplare über vorhandene EAN", "Bekannte EANs zeigen eine Dublettenwarnung mit den getrennten Aktionen „vorhandenes Exemplar öffnen“ und „weiteres Exemplar erfassen“; Medien übernehmen Katalogdaten in den Fragenkatalog, ohne persönliche Exemplardaten zu kopieren."),
    ("4.6.2", "Persönliche Rezensionen & Updatearchiv", "Vorhandene Titel erhalten eigene inhaltliche Rezensionen mit Gesamt- und Einzelwertungen; erfolgreiche Installationen verschieben Bibo-Pakete aus Downloads automatisch nach /opt/gamecollector/updates."),
    ("4.6.1", "Ähnliche-Titel-Vorschau & TMDB-Boxinhalt", "Werkseiten zeigen ähnliche Titel als kompakte Coverleiste mit Besitz- oder Wunschlistenstatus; Film-Boxen übernehmen enthaltene Filme direkt aus TMDB-Film-Links oder IDs."),
    ("4.6.0", "Ähnliche Titel & passende Formatauswahl", "Games, Filme, Serien, Bücher, Musik und Sammelkarten erhalten begründete, bebilderte Empfehlungen mit eigener Vorschau, Wunschliste und direkter Übernahme; Medium und Format werden im Fragenkatalog als passende Auswahlliste angeboten."),
    ("4.5.3", "Sichtbare Coverprüfung & korrekte Staffelboxen", "Cover-Links zeigen im Medienassistenten sofort das tatsächliche Bild und erneut in der Abschlusskontrolle; Komplettboxen einzelner Staffeln werden nicht mehr als komplette Serie gewertet."),
    ("4.5.2", "Komplettbox-Aktionen & Kachelstatistiken", "Staffeln einer Box lassen sich mit Aktionsfeldern gesammelt auswählen; ältere Komplettboxen werden automatisch auf alle Serienstaffeln erweitert und jede Dashboard-Kachel zeigt eine kurze Bestandsaufteilung."),
    ("4.5.1", "Fragenkatalog nach EAN-Treffern", "Gefundene Film-, Serien-, Buch-, Musik- und allgemeine EAN-Daten werden vorausgefüllt in den Assistenten übernommen; gespeichert wird erst nach der Abschlusskontrolle."),
    ("4.5.0", "Geführter Medienassistent", "Ein schrittweiser, medienabhängiger Fragenkatalog erfasst Werk, Ausgabe, Boxinhalt, Zustand, Kaufdaten und Lagerort vollständig und verständlich."),
    ("4.4.1", "Komplettboxen für TV-Serien", "Eine physische Komplett- oder Mehrstaffelbox kann ausgewählten Staffeln gemeinsam zugeordnet werden; Preis und Exemplar werden weiterhin nur einmal summiert."),
    ("4.4.0", "Rechte & Betriebssicherheit", "Einzelrechte für Einträge, Preise, Importe und Benutzerverwaltung, exportierbarer Änderungsnachweis sowie eine zentrale Systemdiagnose."),
    ("4.3.0", "Lager, Inventur & Leihen", "Hierarchische Lagerorte mit QR-Code, mobile Bestandsprüfung und eine übersichtliche Leihverwaltung für das gemeinsame Bibliotheksregister."),
    ("4.2.0", "Planungszentrale", "Monatsbudget, tatsächliche Ausgaben, Wünsche, priorisierte Ziele und deutsche Veröffentlichungsstatus werden gemeinsam geplant."),
    ("4.1.0", "Persönlicher Einstieg", "Zeitabhängige Begrüßung, zentrale Hinzufügen-Seite und Strg/⌘+K für die globale Suche."),
    ("4.0.2", "Automatische Cover-Slider", "Bis zu fünf Cover je Bereich wechseln weich und zeitversetzt; Bewegungsreduzierung und Einzelcover werden respektiert."),
    ("4.0.1", "Cover auf der Startseite", "Die großen Bereichskacheln zeigen echte Cover aus der eigenen Sammlung mit einem lesbaren, ruhigen Bildverlauf."),
    ("4.0.0", "Eine Bibliothek für alles", "Das gemeinsame Register verbindet Werke, Reihen, Ausgaben und Exemplare aller Medienarten – nicht-destruktiv und mit eigener Werkansicht."),
    ("3.5.0", "Dashboard mit Sammlungsassistent", "Eigene Cover als Wasserzeichen und priorisierte nächste Schritte statt eintöniger Kennzahlen."),
    ("3.4.0", "Boxsets richtig abbilden", "Eine Box kann mehrere Filme, Staffeln oder Bände abdecken, ohne ihren Preis mehrfach zu zählen."),
    ("3.3.0", "Mobile Stapel-Erfassung", "Mehrere Barcodes unterwegs sammeln, Mengen und Kaufpreise festhalten und später gesammelt zuordnen."),
    ("3.2.0", "Prüf-Inbox", "Daten-, Preis- und Technikhinweise werden in einer gemeinsamen, handlungsorientierten Inbox gebündelt."),
    ("3.1.0", "Komfort & Stabilität", "Kumulative, vollständig geprüfte Ausgabe mit Release-Übersicht und verständlicher Benutzerrechte-Erklärung."),
    ("3.0.15", "Logische Reihenzählung", "Staffeln, Filme und Bände statt einzelner Datenträger; Split-Boxen werden nicht doppelt gezählt."),
    ("3.0.14", "Einheitliche Ansichten", "Listen-/Cover-Ansicht, weiche Cover-Hintergründe und bessere mobile Bedienung in allen Collector-Bereichen."),
    ("3.0.13", "Transparente Preise", "Preisdetails zeigen Quelle, Zeitstand, Spanne, Historie und die besondere PokéCollector-Herkunft."),
    ("3.0.12", "Saubere Sammlungstrennung", "Bewertungsläufe, Serienabgleiche, Offline-Scans und Diagnose bleiben in ihrer jeweiligen Sammlung."),
    ("3.0.11", "Diagnose", "Verständliche Fehlerseiten, Fehlerkennungen und automatische Template-/Routenprüfung."),
]
